#include <array>
#include <cstddef>
#include <vector>
#include <algorithm>
#include <omp.h>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    bins.fill(0);

    const int max_threads = omp_get_max_threads();
    std::vector<std::array<size_t, 10>> local(static_cast<size_t>(max_threads));
    for (auto &a : local) a.fill(0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        auto &my = local[static_cast<size_t>(tid)];

        #pragma omp for nowait
        for (std::size_t i = 0; i < x.size(); ++i) {
            double v = x[i];

            // Clamp to [0, 100] per problem statement; handle v==100 into last bin.
            if (v < 0.0) v = 0.0;
            if (v > 100.0) v = 100.0;

            std::size_t b = static_cast<std::size_t>(v / 10.0);
            if (b >= 10) b = 9;
            my[b] += 1;
        }

        #pragma omp barrier
        #pragma omp for
        for (int b = 0; b < 10; ++b) {
            std::size_t sum = 0;
            for (int t = 0; t < max_threads; ++t) {
                sum += local[static_cast<size_t>(t)][static_cast<std::size_t>(b)];
            }
            bins[static_cast<std::size_t>(b)] = sum;
        }
    }
}
